#include <iostream>
#include <string>

/*
* @pre c1, c2, c3 en {A, 2, 3, ..., 8, 9, 0, J, Q, K}
* @post Retorna "Trio d'Asos!", "Trio", "Parella", o 
*       "Totes les cartes diferents" segons c1, c2 i c3.
*/

std::string	poker_hand(char c1, char c2, char c3)
{
	char	*a;
	char	*b;
	char	*c;

	a = &c1;
	b = &c2;
	c = &c3;
	if (*a == *b && *b == *c)
	{
		if (*a == 'A')
			return("Trio d'Asos!");
		return ("Trio");
	}
	else if (*a == *b || *b == *c || *a == *c)
		return ("Parella");
	return ("Totes les cartes diferents");
}

