#include <iostream>

/**
 * @pre  n > 0. La entrada contiene al menos una carta (A, 2..9, 0, J, Q, K)
 *       separada por espacios en blanco.
 * @post Se han leido cartas de std::cin hasta completar la primera racha de
 *       n cartas iguales consecutivas, o hasta el final de la entrada.
 *       Escribe "n-Poker of x!" si existe la racha (x = carta), y
 *       "No n-Poker" en caso contrario.
 */

void	ft_GetPockerHand(int n)
{
	char	c;
	char	next;
	int	racha;

	std::cin >> c;
	racha = 1;
	while (racha < n && std::cin >> next)
	{
		if (next == c)
			racha++;
		else
		{
			c = next;
			racha = 1;
		}
	}
	if (racha == n)
		std::cout << n << "-Poker de " << c << "!\n";
	else
		std::cout << "No hi ha " << n << "-Poker\n";
}

int	main(void)
{
	int	nbr;

	std::cin >> nbr;
	ft_GetPockerHand(nbr);
}
